-- PHY 102 (old PHY 124): Electricity, Magnetism and Atomic Physics - CA practice questions
-- =============================================================================
-- 83 original questions on the topics of the PHY 102 CA workbook, the revision sheet
-- and the course notes. Every answer was re-solved and checked numerically; the circled
-- answers in the scan were NOT trusted. Corrections to the scan: 8 + 6 + 2 ohm in series
-- on 120 V carries 7.5 A (scan marked 7.06 A); closest approach of the alpha particle is
-- about 27 fm (the scan option of 270 fm is ten times too large); the age from 15 against
-- 19 counts per minute is about 1886 years (scan 1883). Third-party compiler names and
-- contact details are not used. ADDS ONLY; repeats are skipped.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('Two point charges of $5\ \mu\text{C}$ and $8\ \mu\text{C}$ are $0.20\ \text{m}$ apart in air. What is the magnitude of the force between them?', '["$8.99\\ \\text{N}$","$4.5\\ \\text{N}$","$36\\ \\text{N}$","$2.25\\ \\text{N}$"]'::jsonb, 0, 'Coulomb''s law: $F = kq_1q_2/r^{2} = (8.99\times10^{9})(5\times10^{-6})(8\times10^{-6})/(0.2)^{2} \approx 9\ \text{N}$.', 'Electrostatics'),
  ('A charge of $+8\ \text{nC}$ is at the origin and a charge of $-10\ \text{nC}$ is at $x = 4\ \text{m}$. What is the electric field at $x = 8\ \text{m}$?', '["$4.5\\ \\text{N/C}$ in the $+x$ direction","$4.5\\ \\text{N/C}$ in the $-x$ direction","$6.75\\ \\text{N/C}$ in the $-x$ direction","$1.1\\ \\text{N/C}$ in the $+x$ direction"]'::jsonb, 1, '$E_{1} = kq_1/r^{2} = 1.12\ \text{N/C}$ along $+x$ (distance $8\ \text{m}$). $E_{2} = k|q_2|/r^{2} = 5.62\ \text{N/C}$ towards the negative charge, i.e. along $-x$ (distance $4\ \text{m}$). Net $= 5.62 - 1.12 = 4.5\ \text{N/C}$ along $-x$.', 'Electrostatics'),
  ('A charge of $0.5\ \text{mC}$ gains $30\ \text{J}$ of energy moving between two points. What is the potential difference between them?', '["$15\\ \\text{kV}$","$60\\ \\text{V}$","$60\\ \\text{kV}$","$15\\ \\text{V}$"]'::jsonb, 2, '$V = W/q = 30/(0.5\times10^{-3}) = 6\times10^{4}\ \text{V} = 60\ \text{kV}$.', 'Electrostatics'),
  ('Find the electric field $20\ \text{cm}$ from an isolated point charge of $20\ \mu\text{C}$, and the force it exerts on a $5\ \mu\text{C}$ charge placed there.', '["$4.5\\times10^{6}\\ \\text{N/C};\\ 0.9\\ \\text{N}$","$9\\times10^{5}\\ \\text{N/C};\\ 4.5\\ \\text{N}$","$2.25\\times10^{7}\\ \\text{N/C};\\ 112\\ \\text{N}$","$4.5\\times10^{6}\\ \\text{N/C};\\ 22.5\\ \\text{N}$"]'::jsonb, 3, '$E = kQ/r^{2} = (8.99\times10^{9})(20\times10^{-6})/(0.2)^{2} \approx 4.5\times10^{6}\ \text{N/C}$. Then $F = qE = (5\times10^{-6})(4.5\times10^{6}) = 22.5\ \text{N}$.', 'Electrostatics'),
  ('A large uniformly charged sheet with surface charge density $10^{-4}\ \text{C/m}^{2}$ is immersed in a liquid of relative permittivity $10$. What is the electric field near the sheet?', '["$5.65\\times10^{5}\\ \\text{N/C}$","$1.13\\times10^{6}\\ \\text{N/C}$","$5.65\\times10^{6}\\ \\text{N/C}$","$1.13\\times10^{7}\\ \\text{N/C}$"]'::jsonb, 0, 'For a sheet in a dielectric, $E = \sigma/(2\varepsilon_{0}\varepsilon_{r}) = 10^{-4}/(2\times8.85\times10^{-12}\times10) \approx 5.6\times10^{5}\ \text{N/C}$.', 'Electrostatics'),
  ('The charge on any isolated body is always:', '["any real number times $e$","an integral multiple of the elementary charge $e$","a multiple of $e/3$ for free bodies","always positive"]'::jsonb, 1, 'Charge is quantised: $Q = ne$ with $n$ an integer.', 'Electrostatics'),
  ('An electric dipole consists of charges $\pm q$ separated by a distance $d$. Its dipole moment has magnitude:', '["$q/d$","$qd^{2}$","$qd$","$2q/d$"]'::jsonb, 2, 'The dipole moment is $p = qd$, directed from the negative to the positive charge.', 'Electrostatics'),
  ('At a point on the perpendicular bisector of an electric dipole, the electric field is:', '["perpendicular to the dipole axis","zero","directed along the dipole moment","parallel to the dipole axis and opposite to the dipole moment"]'::jsonb, 3, 'On the equatorial line the components along the bisector cancel and the remainder points antiparallel to $\mathbf{p}$.', 'Electrostatics'),
  ('The SI unit of electric potential, the volt, is equivalent to:', '["$\\text{J C}^{-1}$","$\\text{C J}^{-1}$","$\\text{N C}$","$\\text{J s}^{-1}$"]'::jsonb, 0, '$V = W/q$, so $1\ \text{V} = 1\ \text{J/C}$.', 'Electrostatics'),
  ('Which statement about electric field lines is NOT correct?', '["They begin on positive charges and end on negative charges","They can cross each other where the field is strong","They are closer together where the field is stronger","The tangent to a line gives the direction of the field"]'::jsonb, 1, 'Field lines never cross, because the field at any point has only one direction.', 'Electrostatics'),
  ('Gauss''s law for electricity states that the net electric flux through a closed surface is:', '["$\\varepsilon_{0}q_{\\text{enc}}$","$q_{\\text{enc}}\\,\\varepsilon_{0}^{2}$","$q_{\\text{enc}}/\\varepsilon_{0}$","zero for every closed surface"]'::jsonb, 2, '$\oint \mathbf{E}\cdot d\mathbf{A} = q_{\text{enc}}/\varepsilon_{0}$.', 'Electrostatics'),
  ('Two $6\ \mu\text{F}$ capacitors are connected in series across a $12\ \text{V}$ supply. How much energy is stored in the combination?', '["$8.64\\times10^{-4}\\ \\text{J}$","$4.32\\times10^{-4}\\ \\text{J}$","$1.08\\times10^{-4}\\ \\text{J}$","$2.16\\times10^{-4}\\ \\text{J}$"]'::jsonb, 3, 'The series capacitance is $C = 6\times6/(6 + 6) = 3\ \mu\text{F}$. $U = \tfrac{1}{2}CV^{2} = \tfrac{1}{2}(3\times10^{-6})(144) = 2.16\times10^{-4}\ \text{J}$.', 'Capacitors and Dielectrics'),
  ('A $6\ \mu\text{F}$ capacitor is in series with three $2\ \mu\text{F}$ capacitors that are connected in parallel with one another. What is the equivalent capacitance?', '["$3\\ \\mu\\text{F}$","$4.5\\ \\mu\\text{F}$","$12\\ \\mu\\text{F}$","$1.5\\ \\mu\\text{F}$"]'::jsonb, 0, 'The three in parallel give $6\ \mu\text{F}$. Two equal $6\ \mu\text{F}$ in series give $3\ \mu\text{F}$.', 'Capacitors and Dielectrics'),
  ('A parallel-plate capacitor has plate area $0.020\ \text{m}^{2}$ and plate separation $1.0\ \text{mm}$ in air. Its capacitance is:', '["$1.77\\times10^{-9}\\ \\text{F}$","$1.77\\times10^{-10}\\ \\text{F}$","$1.77\\times10^{-11}\\ \\text{F}$","$1.77\\times10^{-7}\\ \\text{F}$"]'::jsonb, 1, '$C = \varepsilon_{0}A/d = (8.85\times10^{-12})(0.02)/(10^{-3}) \approx 1.77\times10^{-10}\ \text{F}$.', 'Capacitors and Dielectrics'),
  ('A dielectric of constant $\kappa$ completely fills the space between the plates of a capacitor that stays connected to a battery. The stored energy:', '["decreases by a factor $\\kappa$","is unchanged","increases by a factor $\\kappa$","becomes zero"]'::jsonb, 2, 'Capacitance rises to $\kappa C$ while $V$ is fixed, so $U = \tfrac{1}{2}CV^{2}$ increases by $\kappa$.', 'Capacitors and Dielectrics'),
  ('A $2\ \text{k}\Omega$ resistor and a $20\ \mu\text{F}$ capacitor are connected in series to a battery. What is the time constant?', '["$0.4\\ \\text{s}$","$0.004\\ \\text{s}$","$40\\ \\text{s}$","$0.04\\ \\text{s}$"]'::jsonb, 3, '$\tau = RC = (2000)(20\times10^{-6}) = 0.04\ \text{s}$.', 'Capacitors and Dielectrics'),
  ('Resistors of $8\ \Omega$, $6\ \Omega$ and $2\ \Omega$ are connected in series across a $120\ \text{V}$ battery. What is the equivalent resistance and the current?', '["$16\\ \\Omega;\\ 7.5\\ \\text{A}$","$16\\ \\Omega;\\ 7.06\\ \\text{A}$","$17\\ \\Omega;\\ 7.06\\ \\text{A}$","$17\\ \\Omega;\\ 6.02\\ \\text{A}$"]'::jsonb, 0, '$R = 8 + 6 + 2 = 16\ \Omega$. The same current flows in all: $I = V/R = 120/16 = 7.5\ \text{A}$.', 'Current Electricity and DC Circuits'),
  ('Resistors of $2\ \Omega$, $3\ \Omega$ and $4\ \Omega$ are connected in parallel. The equivalent resistance is:', '["$9\\ \\Omega$","$0.92\\ \\Omega$","$0.75\\ \\Omega$","$1.2\\ \\Omega$"]'::jsonb, 1, '$1/R = 1/2 + 1/3 + 1/4 = 13/12$, so $R = 12/13 \approx 0.92\ \Omega$.', 'Current Electricity and DC Circuits'),
  ('A galvanometer of coil resistance $15\ \Omega$ gives full-scale deflection at $10\ \text{mA}$. What shunt, in parallel, converts it into an ammeter reading up to $10\ \text{A}$?', '["$1.5\\ \\Omega$","$0.15\\ \\Omega$","$0.015\\ \\Omega$","$0.0015\\ \\Omega$"]'::jsonb, 2, '$R_{s} = I_{g}G/(I - I_{g}) = (0.01)(15)/(10 - 0.01) \approx 0.015\ \Omega$.', 'Current Electricity and DC Circuits'),
  ('A galvanometer of resistance $40\ \Omega$ gives full-scale deflection at $10\ \text{mA}$. What series resistance converts it into a voltmeter reading up to $100\ \text{V}$?', '["$10\\,000\\ \\Omega$","$9980\\ \\Omega$","$9600\\ \\Omega$","$9960\\ \\Omega$"]'::jsonb, 3, '$R = V/I_{g} - G = 100/0.01 - 40 = 9960\ \Omega$.', 'Current Electricity and DC Circuits'),
  ('In converting a galvanometer into an ammeter, which statement is correct?', '["A low-resistance shunt is connected in parallel with the galvanometer","A multiplier is connected in series with the galvanometer","A high-resistance shunt is connected in series","A multiplier is connected in parallel"]'::jsonb, 0, 'An ammeter must have very low resistance, so a shunt is placed in parallel. A voltmeter uses a series multiplier.', 'Current Electricity and DC Circuits'),
  ('In a potentiometer experiment a standard cell of $6\ \text{V}$ balances at $40\ \text{cm}$. At what length does a cell of e.m.f. $9\ \text{V}$ balance?', '["$27\\ \\text{cm}$","$60\\ \\text{cm}$","$90\\ \\text{cm}$","$40\\ \\text{cm}$"]'::jsonb, 1, 'Balance length is proportional to e.m.f.: $l = 40\times9/6 = 60\ \text{cm}$.', 'Current Electricity and DC Circuits'),
  ('A standard cell of e.m.f. $3\ \text{V}$ balances at $60\ \text{cm}$ on a $100\ \text{cm}$ potentiometer wire. A second cell balances at $80\ \text{cm}$. What is its e.m.f.?', '["$2.25\\ \\text{V}$","$5.0\\ \\text{V}$","$4.0\\ \\text{V}$","$2.0\\ \\text{V}$"]'::jsonb, 2, '$E_{2} = 3\times80/60 = 4.0\ \text{V}$.', 'Current Electricity and DC Circuits'),
  ('A copper wire of cross-section $1.0\ \text{mm}^{2}$ carries $2.0\ \text{A}$. Taking $n = 8.5\times10^{28}\ \text{m}^{-3}$, the drift velocity of the electrons is about:', '["$0.147\\ \\text{m/s}$","$1.47\\times10^{-7}\\ \\text{m/s}$","$1.47\\times10^{-3}\\ \\text{m/s}$","$1.47\\times10^{-4}\\ \\text{m/s}$"]'::jsonb, 3, '$v_{d} = I/(nAe) = 2/[(8.5\times10^{28})(10^{-6})(1.6\times10^{-19})] \approx 1.5\times10^{-4}\ \text{m/s}$.', 'Current Electricity and DC Circuits'),
  ('Find the force on a $50\ \text{cm}$ wire carrying $10\ \text{A}$ in a uniform field of $0.35\ \text{T}$ when the wire makes $60^{\circ}$ with the field.', '["$1.52\\ \\text{N}$","$1.75\\ \\text{N}$","$1.01\\ \\text{N}$","$2.52\\ \\text{N}$"]'::jsonb, 0, '$F = BIL\sin\theta = (0.35)(10)(0.5)\sin60^{\circ} = 1.52\ \text{N}$.', 'Magnetic Fields and Forces'),
  ('What is the magnetic flux density at $2.0\ \text{cm}$ from a long straight wire carrying $10\ \text{A}$ in air?', '["$1.0\\times10^{-2}\\ \\text{T}$","$1.0\\times10^{-4}\\ \\text{T}$","$1.0\\times10^{-6}\\ \\text{T}$","$2.0\\times10^{-4}\\ \\text{T}$"]'::jsonb, 1, '$B = \mu_{0}I/(2\pi r) = (2\times10^{-7})(10)/0.02 = 10^{-4}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A proton moving at $10^{6}\ \text{m/s}$ enters a $0.5\ \text{T}$ field at $60^{\circ}$ to the field. The force on it is:', '["$8\\times10^{-14}\\ \\text{N}$","$6.93\\times10^{-11}\\ \\text{N}$","$6.93\\times10^{-14}\\ \\text{N}$","$3.46\\times10^{-14}\\ \\text{N}$"]'::jsonb, 2, '$F = qvB\sin\theta = (1.6\times10^{-19})(10^{6})(0.5)(0.866) \approx 6.9\times10^{-14}\ \text{N}$.', 'Magnetic Fields and Forces'),
  ('A cable carries $0.02\ \text{A}$ over a $10\ \text{m}$ span at $30^{\circ}$ to a horizontal field of $0.01\ \text{T}$. The magnetic force is:', '["$0.002\\ \\text{N}$","$0.06\\ \\text{N}$","$0.01\\ \\text{N}$","$0.001\\ \\text{N}$"]'::jsonb, 3, '$F = BIL\sin\theta = (0.01)(0.02)(10)(0.5) = 1.0\times10^{-3}\ \text{N}$.', 'Magnetic Fields and Forces'),
  ('A $240\ \text{m}$ wire carries $150\ \text{A}$ at $60^{\circ}$ to a $5\times10^{-5}\ \text{T}$ field. The magnetic force is about:', '["$1.56\\ \\text{N}$","$1.80\\ \\text{N}$","$0.90\\ \\text{N}$","$15.6\\ \\text{N}$"]'::jsonb, 0, '$F = BIL\sin\theta = (5\times10^{-5})(150)(240)(0.866) \approx 1.56\ \text{N}$.', 'Magnetic Fields and Forces'),
  ('An unknown material has relative permeability less than one. It is:', '["paramagnetic and suitable as a core","diamagnetic and unsuitable as a solenoid core","ferromagnetic and suitable as a core","ferromagnetic and unsuitable as a core"]'::jsonb, 1, 'Diamagnetic materials have $\mu_{r} < 1$ and weaken the field slightly. Ferromagnetic materials have $\mu_{r} \gg 1$.', 'Magnetic Fields and Forces'),
  ('A $42\ \text{cm}$ solenoid must produce $0.20\ \text{T}$ at its centre when the current is $3.7\ \text{A}$. How many turns are needed?', '["$1.8\\times10^{3}$ turns","$7.2\\times10^{4}$ turns","$1.8\\times10^{4}$ turns","$3.6\\times10^{3}$ turns"]'::jsonb, 2, '$B = \mu_{0}NI/l$, so $N = Bl/(\mu_{0}I) = (0.2)(0.42)/[(4\pi\times10^{-7})(3.7)] \approx 1.8\times10^{4}$.', 'Magnetic Fields and Forces'),
  ('What is the force on a $200\ \text{cm}$ wire carrying $10\,000\ \text{mA}$ placed at right angles to a $0.45\ \text{T}$ field?', '["$4.5\\ \\text{N}$","$9000\\ \\text{N}$","$0.9\\ \\text{N}$","$9.0\\ \\text{N}$"]'::jsonb, 3, 'Convert to SI: $L = 2\ \text{m}$, $I = 10\ \text{A}$. $F = BIL = (0.45)(10)(2) = 9.0\ \text{N}$.', 'Magnetic Fields and Forces'),
  ('The magnetic moment of a coil of $500$ turns, area $5\ \text{cm}^{2}$, carrying $10\ \text{A}$ is:', '["$2.5\\ \\text{A m}^{2}$","$0.25\\ \\text{A m}^{2}$","$25\\ \\text{A m}^{2}$","$5\\times10^{-3}\\ \\text{A m}^{2}$"]'::jsonb, 0, '$\mu = NIA = (500)(10)(5\times10^{-4}) = 2.5\ \text{A m}^{2}$.', 'Magnetic Fields and Forces'),
  ('A long wire carries $25\ \text{A}$. The magnetic field at $10\ \text{cm}$ from it is:', '["$1.4\\times10^{-4}\\ \\text{T}$","$5.0\\times10^{-5}\\ \\text{T}$","$7.0\\ \\times10^{-5}\\ \\text{T}$","$2.5\\times10^{-4}\\ \\text{T}$"]'::jsonb, 1, '$B = \mu_{0}I/(2\pi r) = (2\times10^{-7})(25)/0.1 = 5\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A solenoid of $400$ turns and length $10\ \text{cm}$ carries $2.0\ \text{A}$. The field near its centre is about:', '["$0.10\\ \\text{T}$","$1.6\\ \\text{T}$","$0.010\\ \\text{T}$","$0.16\\ \\text{T}$"]'::jsonb, 2, '$B = \mu_{0}nI = (4\pi\times10^{-7})(4000)(2) \approx 0.010\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A straight wire carrying $20.5\ \text{A}$ is perpendicular to a $1.50\ \text{T}$ field. The force per metre of wire is:', '["$13.7\\ \\text{N/m}$","$7.5\\ \\text{N/m}$","$3.075\\ \\text{N/m}$","$30.75\\ \\text{N/m}$"]'::jsonb, 3, '$F/L = BI = (1.5)(20.5) = 30.75\ \text{N/m}$.', 'Magnetic Fields and Forces'),
  ('A wire of diameter $2\ \text{mm}$ carries $5\ \text{A}$. The field $20\ \text{cm}$ from its axis is:', '["$5.0\\times10^{-6}\\ \\text{T}$","$2.5\\times10^{-6}\\ \\text{T}$","$5.0\\times10^{-5}\\ \\text{T}$","$0.5\\times10^{-6}\\ \\text{T}$"]'::jsonb, 0, 'Outside the wire it acts as a line current: $B = \mu_{0}I/(2\pi r) = (2\times10^{-7})(5)/0.2 = 5\times10^{-6}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('The Hall coefficient of a conductor depends on:', '["the magnetic field applied","the number of charge carriers per unit volume","the current through the strip","the area of the strip"]'::jsonb, 1, '$R_{H} = 1/(nq)$ is a property of the material.', 'Magnetic Fields and Forces'),
  ('The force on a charge moving in a magnetic field is:', '["along the magnetic field","independent of the speed","directed perpendicular to the velocity of the charge","inversely proportional to the charge"]'::jsonb, 2, '$\mathbf{F} = q\mathbf{v}\times\mathbf{B}$ is perpendicular to $\mathbf{v}$, so it does no work.', 'Magnetic Fields and Forces'),
  ('Which statement about the magnetic flux through a closed surface is correct?', '["It equals the enclosed magnetic charge","It equals $\\mu_{0}$ times the enclosed current","It depends on the enclosed current","It is always zero, because magnetic monopoles do not exist"]'::jsonb, 3, '$\oint \mathbf{B}\cdot d\mathbf{A} = 0$ (Gauss''s law for magnetism).', 'Magnetic Fields and Forces'),
  ('The weber is the unit of:', '["magnetic flux, and $1\\ \\text{Wb} = 1\\ \\text{T m}^{2}$","magnetic field, and $1\\ \\text{Wb} = 1\\ \\text{T/m}^{2}$","inductance, and $1\\ \\text{Wb} = 1\\ \\text{H}$","magnetic moment"]'::jsonb, 0, '$\Phi_{B} = \int B\,dA$, so $1\ \text{Wb} = 1\ \text{T m}^{2}$.', 'Magnetic Fields and Forces'),
  ('The cyclotron frequency of a charge $q$ and mass $m$ in a field $B$ is:', '["$f = \\dfrac{2\\pi m}{qB}$","$f = \\dfrac{qB}{2\\pi m}$","$f = \\dfrac{qB}{m}$","$f = \\dfrac{qBR}{2\\pi m}$"]'::jsonb, 1, 'From $qvB = mv^{2}/R$ we get $\omega = qB/m$, so $f = qB/(2\pi m)$, independent of speed and radius.', 'Magnetic Fields and Forces'),
  ('A $17.0\ \text{cm}$ wire moves at $4.6\ \text{m/s}$ across a $0.25\ \text{T}$ field along a U-shaped conductor of resistance $25\ \Omega$. The induced e.m.f. and current are:', '["$0.196\\ \\text{V};\\ 78\\ \\text{mA}$","$0.78\\ \\text{V};\\ 31\\ \\text{mA}$","$0.196\\ \\text{V};\\ 7.8\\ \\text{mA}$","$1.9\\ \\text{V};\\ 7.8\\ \\text{mA}$"]'::jsonb, 2, '$\varepsilon = Blv = (0.25)(0.17)(4.6) = 0.196\ \text{V}$. $I = \varepsilon/R = 0.196/25 = 7.8\times10^{-3}\ \text{A}$.', 'Electromagnetic Induction'),
  ('A bar magnet''s north pole is moved towards a circular coil. Viewed from the magnet side, the induced current is:', '["clockwise, because the coil attracts the approaching pole","clockwise, because the coil field opposes the increase in flux","anticlockwise, because the coil attracts the approaching pole","anticlockwise, because the coil''s field opposes the increase in flux"]'::jsonb, 3, 'By Lenz''s law the coil''s face becomes a north pole to repel the approaching north pole. Anticlockwise current seen from that side gives a north face.', 'Electromagnetic Induction'),
  ('Faraday''s law in integral form is:', '["$\\oint \\mathbf{E}\\cdot d\\mathbf{l} = -\\dfrac{d}{dt}\\int \\mathbf{B}\\cdot d\\mathbf{A}$","$\\oint \\mathbf{B}\\cdot d\\mathbf{A} = 0$","$\\oint \\mathbf{E}\\cdot d\\mathbf{A} = q/\\varepsilon_{0}$","$\\oint \\mathbf{B}\\cdot d\\mathbf{l} = \\mu_{0}I$"]'::jsonb, 0, 'The induced e.m.f. around a loop equals minus the rate of change of magnetic flux through it.', 'Electromagnetic Induction'),
  ('Which of Maxwell''s equations expresses that there are no isolated magnetic poles?', '["$\\nabla\\cdot\\mathbf{E} = \\rho/\\varepsilon_{0}$","$\\nabla\\cdot\\mathbf{B} = 0$","$\\nabla\\times\\mathbf{E} = -\\partial\\mathbf{B}/\\partial t$","$\\nabla\\times\\mathbf{B} = \\mu_{0}\\mathbf{J}$"]'::jsonb, 1, 'The divergence of $\mathbf{B}$ is zero everywhere: field lines form closed loops.', 'Electromagnetic Induction'),
  ('A vector field $\mathbf{E}$ is called irrotational and solenoidal, respectively, when:', '["$\\nabla\\cdot\\mathbf{E} = 0$ and $\\nabla\\times\\mathbf{E} = 0$","$\\nabla\\times\\mathbf{E} = 0$ and $\\nabla\\cdot\\mathbf{E} = 1$","$\\nabla\\times\\mathbf{E} = 0$ and $\\nabla\\cdot\\mathbf{E} = 0$","$\\nabla\\cdot\\mathbf{E} = \\rho$ and $\\nabla\\times\\mathbf{E} = 0$"]'::jsonb, 2, 'Zero curl means irrotational; zero divergence means solenoidal.', 'Electromagnetic Induction'),
  ('A coil of $50$ turns, each of area $0.04\ \text{m}^{2}$ and total resistance $20\ \Omega$, rotates at $25\ \text{rad/s}$ in a $0.1\ \text{T}$ field. The maximum induced current is:', '["$0.5\\ \\text{A}$","$5.0\\ \\text{A}$","$25\\ \\text{A}$","$0.25\\ \\text{A}$"]'::jsonb, 3, '$\varepsilon_{\max} = NAB\omega = 50(0.04)(0.1)(25) = 5\ \text{V}$. $I_{\max} = 5/20 = 0.25\ \text{A}$.', 'Electromagnetic Induction'),
  ('A transformer has $4800$ primary turns on a $1600\ \text{V}$ mains supply and must deliver $100\ \text{V}$. The number of secondary turns and type of transformer are:', '["$300$ turns; step-down","$300$ turns; step-up","$76\\,800$ turns; step-up","$3$ turns; step-down"]'::jsonb, 0, '$N_{s} = N_{p}V_{s}/V_{p} = 4800(100)/1600 = 300$. The voltage is reduced, so it is a step-down transformer.', 'Electromagnetic Induction'),
  ('A $90\%$ efficient step-down transformer supplies $100\ \text{V}$ at $4\ \text{A}$ from a $1600\ \text{V}$ primary. The primary current is about:', '["$0.25\\ \\text{A}$","$0.28\\ \\text{A}$","$0.31\\ \\text{A}$","$4.0\\ \\text{A}$"]'::jsonb, 1, 'Output power $= 400\ \text{W}$. Input power $= 400/0.9 = 444\ \text{W}$. $I_{p} = 444/1600 = 0.28\ \text{A}$.', 'Electromagnetic Induction'),
  ('In a series LR circuit on a battery of e.m.f. $V$ with resistance $R$ and inductance $L$, the initial rate of rise of current is:', '["$V/R$","$V/(L + R)$","$V/L$","$VR/L$"]'::jsonb, 2, 'At $t = 0$, $I = 0$, so $V = L\,dI/dt$ and $dI/dt = V/L$.', 'Electromagnetic Induction'),
  ('Two LR circuits have equal resistance, but circuit A has twice the inductance of B, on identical batteries. Which statement is correct?', '["A reaches its final current sooner, because it has more inductance","They reach it at the same rate because $R$ is equal","They have different final currents","B reaches its final current sooner, because its time constant $L/R$ is smaller"]'::jsonb, 3, 'The final current is $V/R$ for both. The time constant is $\tau = L/R$, so B (smaller $L$) is faster.', 'Electromagnetic Induction'),
  ('The dimensions of mutual inductance $M$, given $1\ \text{H} = 1\ \Omega\,\text{s}$, are:', '["$ML^{2}T^{-2}I^{-2}$","$ML^{2}T^{-2}I^{-1}$","$ML^{2}T^{-1}I^{-2}$","$MLT^{-2}I^{-2}$"]'::jsonb, 0, '$\Omega = ML^{2}T^{-3}I^{-2}$, so $\Omega\,\text{s} = ML^{2}T^{-2}I^{-2}$.', 'Electromagnetic Induction'),
  ('A long solenoid of length $l$ and $N$ turns has magnetic energy density $u$ inside. The current is:', '["$I = \\dfrac{l}{N}\\sqrt{\\dfrac{u}{2\\mu_{0}}}$","$I = \\dfrac{l}{N}\\sqrt{\\dfrac{2u}{\\mu_{0}}}$","$I = \\dfrac{N}{l}\\sqrt{\\dfrac{2u}{\\mu_{0}}}$","$I = \\dfrac{l}{N}\\,\\dfrac{2u}{\\mu_{0}}$"]'::jsonb, 1, '$u = B^{2}/(2\mu_{0})$ gives $B = \sqrt{2\mu_{0}u}$. With $B = \mu_{0}NI/l$: $I = (l/N)\sqrt{2u/\mu_{0}}$.', 'Electromagnetic Induction'),
  ('A supply voltage is rated $240\ \text{V}$ (r.m.s.). The peak voltage is:', '["$169.7\\ \\text{V}$","$240\\ \\text{V}$","$339.4\\ \\text{V}$","$480\\ \\text{V}$"]'::jsonb, 2, '$V_{0} = \sqrt{2}V_{rms} = 1.414\times240 = 339.4\ \text{V}$.', 'Alternating Current'),
  ('An a.c. of r.m.s. value $3.0\ \text{A}$ flows through a resistor. The peak current is:', '["$2.12\\ \\text{A}$","$3.46\\ \\text{A}$","$0.47\\ \\text{A}$","$4.24\\ \\text{A}$"]'::jsonb, 3, '$I_{0} = \sqrt{2}(3.0) = 4.24\ \text{A}$.', 'Alternating Current'),
  ('A $240\ \text{V}$ r.m.s. source delivers $300\ \text{W}$ to a hot wire. The resistance of the wire is:', '["$192\\ \\Omega$","$125\\ \\Omega$","$0.84\\ \\Omega$","$176\\ \\Omega$"]'::jsonb, 0, '$R = V^{2}/P = 240^{2}/300 = 192\ \Omega$.', 'Alternating Current'),
  ('A $100\ \mu\text{F}$ capacitor is connected to a $12\ \text{V}$, $50\ \text{Hz}$ supply. Its reactance is:', '["$2.42\\ \\Omega$","$31.8\\ \\Omega$","$1.64\\ \\Omega$","$318\\ \\Omega$"]'::jsonb, 1, '$X_{C} = 1/(2\pi fC) = 1/(2\pi\cdot50\cdot10^{-4}) = 31.8\ \Omega$.', 'Alternating Current'),
  ('What is the potential difference across a $5\ \text{H}$ inductor carrying $20\ \text{mA}$ of a.c. at $50\ \text{Hz}$?', '["$21.1\\ \\text{V}$","$1.46\\ \\text{V}$","$31.4\\ \\text{V}$","$314\\ \\text{V}$"]'::jsonb, 2, '$X_{L} = 2\pi fL = 1571\ \Omega$. $V = IX_{L} = (0.02)(1571) = 31.4\ \text{V}$.', 'Alternating Current'),
  ('A $4\ \mu\text{F}$ capacitor carries $5\ \text{mA}$ of $60\ \text{Hz}$ a.c. The potential difference across it is:', '["$1.1\\ \\text{V}$","$2.2\\ \\text{V}$","$33\\ \\text{V}$","$3.3\\ \\text{V}$"]'::jsonb, 3, '$X_{C} = 1/(2\pi\cdot60\cdot4\times10^{-6}) = 663\ \Omega$. $V = IX_{C} = (0.005)(663) = 3.3\ \text{V}$.', 'Alternating Current'),
  ('Heat is dissipated at $20\ \text{W}$ in a $5\ \Omega$ resistor by a.c. The r.m.s. current is:', '["$2\\ \\text{A}$","$4\\ \\text{A}$","$100\\ \\text{A}$","$50\\ \\text{A}$"]'::jsonb, 0, '$P = I^{2}R$, so $I = \sqrt{20/5} = 2\ \text{A}$.', 'Alternating Current'),
  ('A $12\ \text{V}$ r.m.s. supply at $100\ \text{Hz}$ is connected to a $2.2\ \mu\text{F}$ capacitor. The r.m.s. current is about:', '["$30\\ \\text{mA}$","$17\\ \\text{mA}$","$100\\ \\text{mA}$","$50\\ \\text{mA}$"]'::jsonb, 1, '$X_{C} = 1/(2\pi\cdot100\cdot2.2\times10^{-6}) = 723\ \Omega$. $I = 12/723 = 16.6\ \text{mA}$.', 'Alternating Current'),
  ('An oscilloscope with sensitivity $5\ \text{V/cm}$ shows a waveform $20\ \text{cm}$ high peak-to-peak. The r.m.s. voltage is:', '["$70.7\\ \\text{V}$","$100\\ \\text{V}$","$35.4\\ \\text{V}$","$50\\ \\text{V}$"]'::jsonb, 2, '$V_{pp} = 100\ \text{V}$, so $V_{0} = 50\ \text{V}$ and $V_{rms} = 50/\sqrt{2} = 35.4\ \text{V}$.', 'Alternating Current'),
  ('At what frequency does a $10.0\ \text{mH}$ inductor have a reactance of $8\ \Omega$?', '["$40\\,000/\\pi\\ \\text{Hz}$","$40/\\pi\\ \\text{Hz}$","$1.6\\pi\\ \\text{Hz}$","$400/\\pi\\ \\text{Hz}$"]'::jsonb, 3, '$f = X_{L}/(2\pi L) = 8/(2\pi\cdot0.01) = 400/\pi \approx 127\ \text{Hz}$.', 'Alternating Current'),
  ('Which statement is true of a series RLC circuit at resonance?', '["The current is a maximum and the impedance equals $R$","The impedance is a maximum","The resistance is zero","The reactances are unequal"]'::jsonb, 0, 'At resonance $X_{L} = X_{C}$, so $Z = R$ is a minimum and the current is a maximum.', 'Alternating Current'),
  ('A $5\ \text{H}$ inductor and a variable capacitor in series are tuned to $91.1\ \text{MHz}$. The capacitance is:', '["$3.3\\times10^{-12}\\ \\text{F}$","$6.1\\times10^{-19}\\ \\text{F}$","$6.2\\times10^{-6}\\ \\text{F}$","$6.1\\times10^{-16}\\ \\text{F}$"]'::jsonb, 1, '$f = 1/(2\pi\sqrt{LC})$, so $C = 1/[(2\pi f)^{2}L] = 1/[(5.72\times10^{8})^{2}(5)] \approx 6.1\times10^{-19}\ \text{F}$.', 'Alternating Current'),
  ('A $50\ \text{mH}$ inductor is connected across $V = 30\sin(2000\pi t)$. What is the reactance, and how does the voltage relate to the current?', '["$314\\ \\Omega$; the voltage lags the current by $\\pi/2$","$3.2\\ \\Omega$; the voltage leads the current by $\\pi/2$","$314\\ \\Omega$; the voltage leads the current by $\\pi/2$","$3.2\\ \\Omega$; the voltage lags the current by $\\pi/2$"]'::jsonb, 2, '$\omega = 2000\pi$, so $X_{L} = \omega L = 2000\pi(0.05) = 314\ \Omega$. In a pure inductor the voltage leads the current by $90^{\circ}$.', 'Alternating Current'),
  ('What is the radius of the third excited state of a hydrogen-like atom with $Z = 1$ and ground-state radius $a_{0}$?', '["$9a_{0}$","$4a_{0}$","$64a_{0}$","$16a_{0}$"]'::jsonb, 3, 'The third excited state is $n = 4$. $r_{n} = n^{2}a_{0}/Z = 16a_{0}$.', 'Atomic and Nuclear Physics'),
  ('Deuterium has mass $2.014102\ \text{u}$. With $m_{p} = 1.007825\ \text{u}$, $m_{n} = 1.008665\ \text{u}$ and $1\ \text{u} = 931.49\ \text{MeV}$, the binding energy per nucleon is:', '["$1.11\\ \\text{MeV}$","$2.22\\ \\text{MeV}$","$0.56\\ \\text{MeV}$","$4.45\\ \\text{MeV}$"]'::jsonb, 0, 'Mass defect $= 0.002388\ \text{u}$, giving $2.224\ \text{MeV}$ in total. Per nucleon: $2.224/2 = 1.11\ \text{MeV}$.', 'Atomic and Nuclear Physics'),
  ('A proton and an electron have the same kinetic energy and $m_{p} = 1800\,m_{e}$. The ratio $\lambda_{p}:\lambda_{e}$ is about:', '["$1 : 1800$","$1 : 42$","$1 : 1$","$2 : 3$"]'::jsonb, 1, '$\lambda = h/\sqrt{2mK}\propto 1/\sqrt{m}$. So $\lambda_{p}/\lambda_{e} = \sqrt{m_{e}/m_{p}} = 1/\sqrt{1800} \approx 1/42$.', 'Atomic and Nuclear Physics'),
  ('Light of wavelength $430\ \text{nm}$ falls on Cs ($2.14\ \text{eV}$), K ($2.30\ \text{eV}$), Na ($2.75\ \text{eV}$), Ca ($3.20\ \text{eV}$) and Mo ($4.17\ \text{eV}$). Which metals emit photoelectrons?', '["Cs and K only","Ca and Mo only","Cs, K and Na only","All five metals"]'::jsonb, 2, '$E = hc/\lambda = 1240/430 = 2.88\ \text{eV}$. Emission needs $E > \phi$: Cs, K and Na.', 'Atomic and Nuclear Physics'),
  ('Which result is a direct consequence of Bohr''s atomic theory?', '["$L = (n + 1)\\hbar$","$L = nh$","$L = \\tfrac{1}{2}n\\hbar$","$L = n\\hbar$"]'::jsonb, 3, 'Bohr postulated that angular momentum is quantised: $L = n\hbar$, with $n = 1, 2, 3, \ldots$', 'Atomic and Nuclear Physics'),
  ('An alpha particle of speed $2\times10^{7}\ \text{m/s}$ is fired directly at a gold nucleus ($Z = 79$). The distance of closest approach is about:', '["$27\\ \\text{fm}$","$270\\ \\text{fm}$","$2.7\\ \\text{nm}$","$2.7\\ \\text{fm}$"]'::jsonb, 0, 'At closest approach all the kinetic energy is potential: $\tfrac{1}{2}mv^{2} = k(2e)(79e)/r$. $K = 1.33\times10^{-12}\ \text{J}$, so $r = 2.75\times10^{-14}\ \text{m} \approx 27\ \text{fm}$.', 'Atomic and Nuclear Physics'),
  ('All of the following were challenges to classical physics at the end of the 19th century EXCEPT:', '["black-body radiation","the deflection of electrons by electric and magnetic fields","the photoelectric effect","atomic line spectra"]'::jsonb, 1, 'Black-body radiation, the photoelectric effect and atomic spectra could not be explained classically. The deflection of electrons by fields was well understood.', 'Atomic and Nuclear Physics'),
  ('Sodium (work function $2.75\ \text{eV}$) is illuminated with $300\ \text{nm}$ light. The maximum photoelectron speed is about:', '["$7.0\\times10^{-5}\\ \\text{m/s}$","$4.9\\times10^{5}\\ \\text{m/s}$","$7.0\\times10^{5}\\ \\text{m/s}$","$9.7\\times10^{5}\\ \\text{m/s}$"]'::jsonb, 2, '$E = 1240/300 = 4.13\ \text{eV}$, so $K_{\max} = 1.38\ \text{eV} = 2.2\times10^{-19}\ \text{J}$. $v = \sqrt{2K/m} \approx 7.0\times10^{5}\ \text{m/s}$.', 'Atomic and Nuclear Physics'),
  ('An electron moving at $10^{7}\ \text{m/s}$ has a de Broglie wavelength of about (take $h = 6.6\times10^{-34}\ \text{J s}$, $m = 9.1\times10^{-31}\ \text{kg}$):', '["$9.1\\times10^{-24}\\ \\text{m}$","$9.1\\times10^{-27}\\ \\text{m}$","$7.3\\times10^{-9}\\ \\text{m}$","$7.3\\times10^{-11}\\ \\text{m}$"]'::jsonb, 3, '$\lambda = h/(mv) = 6.6\times10^{-34}/[(9.1\times10^{-31})(10^{7})] = 7.3\times10^{-11}\ \text{m}$.', 'Atomic and Nuclear Physics'),
  ('$^{56}_{26}\text{Fe}$ has atomic mass $55.9349\ \text{u}$ ($m_{H} = 1.00783\ \text{u}$, $m_{n} = 1.00866\ \text{u}$). Its binding energy per nucleon is:', '["$8.79\\ \\text{MeV}$","$492\\ \\text{MeV}$","$931\\ \\text{MeV}$","$0.53\\ \\text{MeV}$"]'::jsonb, 0, 'Mass defect $= 26(1.00783) + 30(1.00866) - 55.9349 = 0.5285\ \text{u}$, i.e. $492\ \text{MeV}$. Per nucleon: $492/56 = 8.79\ \text{MeV}$.', 'Atomic and Nuclear Physics'),
  ('An electron is confined to $0.10\ \text{nm}$. Using $\Delta x\,\Delta p = h/4\pi$, the minimum uncertainty in its speed is about:', '["$5.8\\times10^{-5}\\ \\text{m/s}$","$5.8\\times10^{5}\\ \\text{m/s}$","$1.2\\times10^{6}\\ \\text{m/s}$","$5.3\\times10^{-2}\\ \\text{m/s}$"]'::jsonb, 1, '$\Delta v = h/(4\pi m\,\Delta x) = 6.63\times10^{-34}/[4\pi(9.11\times10^{-31})(10^{-10})] \approx 5.8\times10^{5}\ \text{m/s}$.', 'Atomic and Nuclear Physics'),
  ('A bone fragment gives $20$ counts/min; fresh bone gives $25$ counts/min. With a carbon half-life of $5530$ years, the age is about:', '["$1648\\ \\text{years}$","$17\\,185\\ \\text{years}$","$1780\\ \\text{years}$","$3560\\ \\text{years}$"]'::jsonb, 2, '$t = T_{1/2}\ln(A_{0}/A)/\ln2 = 5530\ln(1.25)/0.693 \approx 1780\ \text{years}$.', 'Atomic and Nuclear Physics'),
  ('A bone gives $15$ counts/min and fresh bone $19$ counts/min. With a half-life of $5530$ years, the age is about:', '["$1648\\ \\text{years}$","$1780\\ \\text{years}$","$17\\,185\\ \\text{years}$","$1886\\ \\text{years}$"]'::jsonb, 3, '$t = 5530\ln(19/15)/\ln2 = 5530(0.2364)/0.693 \approx 1886\ \text{years}$.', 'Atomic and Nuclear Physics'),
  ('Polonium $^{214}_{84}\text{Po}$ undergoes alpha decay. The daughter nucleus is:', '["$^{210}_{82}\\text{Pb}$","$^{214}_{82}\\text{Pb}$","$^{210}_{84}\\text{Pb}$","$^{218}_{86}\\text{Rn}$"]'::jsonb, 0, 'An alpha particle carries away $2$ protons and $2$ neutrons: $A = 214 - 4 = 210$, $Z = 84 - 2 = 82$ (lead).', 'Atomic and Nuclear Physics'),
  ('Which of the following is NOT a property of X-rays?', '["They ionise gases they pass through","They are deflected by electric and magnetic fields","They affect photographic plates","They are electromagnetic waves of very short wavelength"]'::jsonb, 1, 'X-rays are uncharged photons, so fields do not deflect them.', 'Atomic and Nuclear Physics'),
  ('A helium nucleus is the same as:', '["a beta particle","a gamma ray","an alpha particle","an X-ray"]'::jsonb, 2, 'An alpha particle is two protons and two neutrons, i.e. $^{4}_{2}\text{He}$.', 'Atomic and Nuclear Physics')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where (subject_name ilike 'PHY 102%' or subject_id = 'phy-124-electricity-magnetism-atomic')
     and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'phy-124-electricity-magnetism-atomic'),
       coalesce(t.subject_name, 'PHY 102: Electricity, Magnetism and Atomic Physics'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering'),
       coalesce(t.department, 'Physics and Astronomy'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'second'),
       coalesce(t.units, 3)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'phy-124-electricity-magnetism-atomic') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_id = 'phy-124-electricity-magnetism-atomic'
 group by 1, 2;
-- PHY 102 (old PHY 124): second set of 46 questions - sources of magnetic field, inductance,
-- Maxwell's equations, more electrostatics, DC circuits and atomic/nuclear physics.
-- All answers re-solved and checked numerically. Original wording; ADDS ONLY, repeats skipped.
with src (question, options, correct_index, explanation, topic) as (
values
  ('A circular loop of radius $10\ \text{cm}$ carries $5.0\ \text{A}$. The magnetic field at its centre is:', '["$1.57\\times10^{-5}\\ \\text{T}$","$6.28\\times10^{-5}\\ \\text{T}$","$3.14\\times10^{-5}\\ \\text{T}$","$9.87\\times10^{-5}\\ \\text{T}$"]'::jsonb, 2, 'At the centre of a loop, $B = \mu_{0}I/(2R) = (4\pi\times10^{-7})(5)/(0.2) = 3.1\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A flat coil of $20$ turns and radius $5.0\ \text{cm}$ carries $2.0\ \text{A}$. The field at its centre is:', '["$2.51\\times10^{-5}\\ \\text{T}$","$1.01\\times10^{-3}\\ \\text{T}$","$2.51\\times10^{-4}\\ \\text{T}$","$5.03\\times10^{-4}\\ \\text{T}$"]'::jsonb, 3, '$B = \mu_{0}NI/(2R) = (4\pi\times10^{-7})(20)(2)/(0.1) = 5.0\times10^{-4}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A loop of radius $4.0\ \text{cm}$ carries $3.0\ \text{A}$. What is the field on its axis at $3.0\ \text{cm}$ from the centre?', '["$2.41\\times10^{-5}\\ \\text{T}$","$4.83\\times10^{-5}\\ \\text{T}$","$1.21\\times10^{-5}\\ \\text{T}$","$4.71\\times10^{-5}\\ \\text{T}$"]'::jsonb, 0, '$B = \dfrac{\mu_{0}IR^{2}}{2(R^{2} + z^{2})^{3/2}} = \dfrac{(4\pi\times10^{-7})(3)(0.04)^{2}}{2(0.0025)^{3/2}} \approx 2.4\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('A circular arc of radius $20\ \text{cm}$ subtends $90^{\circ}$ at its centre and carries $10\ \text{A}$. The field at the centre is:', '["$1.57\\times10^{-5}\\ \\text{T}$","$7.85\\times10^{-6}\\ \\text{T}$","$3.14\\times10^{-5}\\ \\text{T}$","$3.93\\times10^{-6}\\ \\text{T}$"]'::jsonb, 1, 'A $90^{\circ}$ arc is one quarter of a loop: $B = \tfrac{1}{4}\mu_{0}I/(2R) = (4\pi\times10^{-7})(10)/(8\times0.2) = 7.85\times10^{-6}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('Two long parallel wires $5.0\ \text{cm}$ apart carry $10\ \text{A}$ and $20\ \text{A}$ in the same direction. The force per metre between them is:', '["$8\\times10^{-4}\\ \\text{N/m}$, repulsive","$1.6\\times10^{-3}\\ \\text{N/m}$, attractive","$8\\times10^{-4}\\ \\text{N/m}$, attractive","$4\\times10^{-4}\\ \\text{N/m}$, repulsive"]'::jsonb, 2, '$F/L = \mu_{0}I_{1}I_{2}/(2\pi d) = (2\times10^{-7})(10)(20)/0.05 = 8\times10^{-4}\ \text{N/m}$. Parallel currents attract.', 'Magnetic Fields and Forces'),
  ('Ampere''s law states that $\oint \mathbf{B}\cdot d\mathbf{l}$ around a closed path equals:', '["$I_{\\text{enc}}/\\mu_{0}$","$\\mu_{0}$ times the total current of the whole circuit","zero for every closed path","$\\mu_{0}I_{\\text{enc}}$"]'::jsonb, 3, 'Only the current enclosed by the path counts: $\oint \mathbf{B}\cdot d\mathbf{l} = \mu_{0}I_{\text{enc}}$.', 'Magnetic Fields and Forces'),
  ('A toroid has $500$ turns and carries $2.0\ \text{A}$. The field at a radius of $15\ \text{cm}$ inside the toroid is:', '["$1.33\\times10^{-3}\\ \\text{T}$","$6.67\\times10^{-4}\\ \\text{T}$","$2.67\\times10^{-3}\\ \\text{T}$","$1.33\\times10^{-2}\\ \\text{T}$"]'::jsonb, 0, '$B = \mu_{0}NI/(2\pi r) = (4\pi\times10^{-7})(500)(2)/(2\pi\times0.15) = 1.33\times10^{-3}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('Outside an ideal long solenoid, the magnetic field is:', '["equal to the field inside","approximately zero","twice the field inside","infinite near the windings"]'::jsonb, 1, 'For an ideal solenoid, Ampere''s law applied to a loop outside gives $B \approx 0$.', 'Magnetic Fields and Forces'),
  ('A long straight wire of radius $2.0\ \text{cm}$ carries a uniform current of $5.0\ \text{A}$. The field inside it at $1.0\ \text{cm}$ from the axis is:', '["$5\\times10^{-5}\\ \\text{T}$","$1.25\\times10^{-5}\\ \\text{T}$","$2.5\\times10^{-5}\\ \\text{T}$","$1\\times10^{-4}\\ \\text{T}$"]'::jsonb, 2, 'Inside, $I_{\text{enc}} = I(r/R)^{2}$. So $B = \mu_{0}Ir/(2\pi R^{2}) = (2\times10^{-7})(5)(0.01)/(0.02)^{2} = 2.5\times10^{-5}\ \text{T}$.', 'Magnetic Fields and Forces'),
  ('According to the Biot-Savart law, the field element $d\mathbf{B}$ due to a current element $I\,d\mathbf{l}$ at displacement $\mathbf{r}$ is proportional to:', '["$I\\,d\\mathbf{l}\\cdot\\hat{\\mathbf{r}}/r$","$I\\,d\\mathbf{l}\\times\\hat{\\mathbf{r}}/r^{3}\\ \\text{only for straight wires}$","$I\\,r^{2}\\,d\\mathbf{l}$","$I\\,d\\mathbf{l}\\times\\hat{\\mathbf{r}}/r^{2}$"]'::jsonb, 3, '$d\mathbf{B} = \dfrac{\mu_{0}}{4\pi}\dfrac{I\,d\mathbf{l}\times\hat{\mathbf{r}}}{r^{2}}$: perpendicular to both the element and $\hat{\mathbf{r}}$, falling off as $1/r^{2}$.', 'Magnetic Fields and Forces'),
  ('A solenoid has $1000$ turns, length $50\ \text{cm}$ and cross-sectional area $4.0\ \text{cm}^{2}$. Its self-inductance is about:', '["$1.01\\times10^{-3}\\ \\text{H}$","$1.01\\times10^{-2}\\ \\text{H}$","$1.01\\times10^{-4}\\ \\text{H}$","$2.01\\times10^{-3}\\ \\text{H}$"]'::jsonb, 0, '$L = \mu_{0}N^{2}A/l = (4\pi\times10^{-7})(10^{6})(4\times10^{-4})/0.5 = 1.0\times10^{-3}\ \text{H}$.', 'Electromagnetic Induction'),
  ('How much energy is stored in a $0.20\ \text{H}$ inductor carrying $3.0\ \text{A}$?', '["$1.8\\ \\text{J}$","$0.90\\ \\text{J}$","$0.60\\ \\text{J}$","$0.45\\ \\text{J}$"]'::jsonb, 1, '$U = \tfrac{1}{2}LI^{2} = \tfrac{1}{2}(0.2)(9) = 0.90\ \text{J}$.', 'Electromagnetic Induction'),
  ('The current in a $0.50\ \text{H}$ inductor changes uniformly from $0$ to $4.0\ \text{A}$ in $10\ \text{ms}$. The magnitude of the induced e.m.f. is:', '["$20\\ \\text{V}$","$2.0\\ \\text{V}$","$200\\ \\text{V}$","$0.2\\ \\text{V}$"]'::jsonb, 2, '$|\varepsilon| = L\,|\Delta I/\Delta t| = 0.5\times4/0.01 = 200\ \text{V}$.', 'Electromagnetic Induction'),
  ('A $0.50\ \text{H}$ inductor is in series with a $25\ \Omega$ resistor. The time constant of the circuit is:', '["$50\\ \\text{s}$","$12.5\\ \\text{s}$","$0.20\\ \\text{s}$","$0.020\\ \\text{s}$"]'::jsonb, 3, '$\tau = L/R = 0.5/25 = 0.020\ \text{s}$.', 'Electromagnetic Induction'),
  ('A $12\ \text{V}$ battery is switched onto a series LR circuit with $R = 6\ \Omega$ and $\tau = L/R$. After one time constant the current is about:', '["$1.26\\ \\text{A}$","$2.00\\ \\text{A}$","$0.74\\ \\text{A}$","$1.00\\ \\text{A}$"]'::jsonb, 0, '$I = (V/R)(1 - e^{-t/\tau})$. At $t = \tau$: $I = 2(1 - 0.368) = 1.26\ \text{A}$, which is $63\%$ of the final value.', 'Electromagnetic Induction'),
  ('A coil of $200$ turns has the flux through it change uniformly from $0.50\ \text{mWb}$ to $0.10\ \text{mWb}$ in $20\ \text{ms}$. The magnitude of the induced e.m.f. is:', '["$0.4\\ \\text{V}$","$4.0\\ \\text{V}$","$20\\ \\text{V}$","$0.02\\ \\text{V}$"]'::jsonb, 1, '$|\varepsilon| = N|\Delta\Phi|/\Delta t = 200(0.4\times10^{-3})/0.02 = 4.0\ \text{V}$.', 'Electromagnetic Induction'),
  ('A rod of length $0.50\ \text{m}$ moves at $2.0\ \text{m/s}$ perpendicular to a field of $0.40\ \text{T}$, and the circuit has resistance $0.20\ \Omega$. The current and the force needed to keep it moving at constant speed are:', '["$2.0\\ \\text{A};\\ 0.80\\ \\text{N}$","$0.40\\ \\text{A};\\ 0.20\\ \\text{N}$","$2.0\\ \\text{A};\\ 0.40\\ \\text{N}$","$4.0\\ \\text{A};\\ 0.40\\ \\text{N}$"]'::jsonb, 2, '$\varepsilon = Blv = (0.4)(0.5)(2) = 0.4\ \text{V}$, so $I = 0.4/0.2 = 2.0\ \text{A}$. The magnetic force is $F = BIl = (0.4)(2)(0.5) = 0.40\ \text{N}$. Check: power $Fv = 0.8\ \text{W} = I^{2}R$.', 'Electromagnetic Induction'),
  ('Lenz''s law is a statement of the conservation of:', '["charge","linear momentum","mass","energy"]'::jsonb, 3, 'If the induced current aided the change in flux, energy would be created from nothing. The opposing direction makes the work done against the induced force the source of the electrical energy.', 'Electromagnetic Induction'),
  ('Displacement current in a charging capacitor is produced by:', '["a changing electric field between the plates","the movement of charges across the gap","a steady magnetic field","the resistance of the wires"]'::jsonb, 0, 'Maxwell added $I_{d} = \varepsilon_{0}\,d\Phi_{E}/dt$ to Ampere''s law, so a changing electric flux acts like a current in producing a magnetic field.', 'Electromagnetic Induction'),
  ('Maxwell''s equations predict that electromagnetic waves travel in vacuum at a speed equal to:', '["$\\sqrt{\\mu_{0}\\varepsilon_{0}}$","$1/\\sqrt{\\mu_{0}\\varepsilon_{0}}$","$\\mu_{0}/\\varepsilon_{0}$","$\\sqrt{\\varepsilon_{0}/\\mu_{0}}$"]'::jsonb, 1, 'Combining Maxwell''s equations gives a wave equation with speed $c = 1/\sqrt{\mu_{0}\varepsilon_{0}} \approx 3.0\times10^{8}\ \text{m/s}$.', 'Electromagnetic Induction'),
  ('In an electromagnetic wave travelling in vacuum, the electric and magnetic fields are:', '["parallel to each other and perpendicular to travel","both parallel to the direction of travel","perpendicular to each other and to the direction of travel","perpendicular to each other but along the direction of travel"]'::jsonb, 2, 'Electromagnetic waves are transverse, with $\mathbf{E}\perp\mathbf{B}\perp\mathbf{k}$ and $E = cB$.', 'Electromagnetic Induction'),
  ('The electric field amplitude of an electromagnetic wave in vacuum is $6.0\ \text{V/m}$. The magnetic field amplitude is:', '["$1.8\\times10^{9}\\ \\text{T}$","$2.0\\times10^{-6}\\ \\text{T}$","$6.0\\times10^{-8}\\ \\text{T}$","$2.0\\times10^{-8}\\ \\text{T}$"]'::jsonb, 3, '$B_{0} = E_{0}/c = 6/(3\times10^{8}) = 2.0\times10^{-8}\ \text{T}$.', 'Electromagnetic Induction'),
  ('A conducting sphere of radius $10\ \text{cm}$ carries a charge of $5.0\ \text{nC}$. What is the electric field at $30\ \text{cm}$ from its centre?', '["$500\\ \\text{N/C}$","$4500\\ \\text{N/C}$","$150\\ \\text{N/C}$","$0$"]'::jsonb, 0, 'Outside a spherical charge distribution the field is that of a point charge at the centre: $E = kQ/r^{2} = (8.99\times10^{9})(5\times10^{-9})/(0.3)^{2} = 500\ \text{N/C}$.', 'Electrostatics'),
  ('Inside a hollow conducting sphere carrying a charge, the electric field is:', '["$kQ/R^{2}$","zero","directed radially inwards","uniform and non-zero"]'::jsonb, 1, 'By Gauss''s law no net charge is enclosed inside the cavity, so $E = 0$. The charge resides on the outer surface.', 'Electrostatics'),
  ('An infinitely long line of charge has linear density $2.0\ \mu\text{C/m}$. The electric field at $0.50\ \text{m}$ is:', '["$3.6\\times10^{4}\\ \\text{N/C}$","$1.44\\times10^{5}\\ \\text{N/C}$","$7.19\\times10^{4}\\ \\text{N/C}$","$7.19\\times10^{2}\\ \\text{N/C}$"]'::jsonb, 2, '$E = \lambda/(2\pi\varepsilon_{0}r) = 2k\lambda/r = 2(8.99\times10^{9})(2\times10^{-6})/0.5 = 7.2\times10^{4}\ \text{N/C}$.', 'Electrostatics'),
  ('An infinite non-conducting sheet carries a surface charge density of $3.0\ \mu\text{C/m}^{2}$. The field near it is:', '["$3.39\\times10^{5}\\ \\text{N/C}$","$8.47\\times10^{4}\\ \\text{N/C}$","$6.78\\times10^{5}\\ \\text{N/C}$","$1.69\\times10^{5}\\ \\text{N/C}$"]'::jsonb, 3, '$E = \sigma/(2\varepsilon_{0}) = 3\times10^{-6}/(2\times8.85\times10^{-12}) = 1.7\times10^{5}\ \text{N/C}$.', 'Electrostatics'),
  ('What is the electric potential $20\ \text{cm}$ from a point charge of $4.0\ \text{nC}$?', '["$180\\ \\text{V}$","$900\\ \\text{V}$","$36\\ \\text{V}$","$18\\ \\text{V}$"]'::jsonb, 0, '$V = kq/r = (8.99\times10^{9})(4\times10^{-9})/0.2 = 180\ \text{V}$.', 'Electrostatics'),
  ('An electron is accelerated from rest through a potential difference of $1000\ \text{V}$. Its kinetic energy is:', '["$1.6\\times10^{-19}\\ \\text{J}$","$1.6\\times10^{-16}\\ \\text{J}$","$1.6\\times10^{-13}\\ \\text{J}$","$1.0\\times10^{3}\\ \\text{J}$"]'::jsonb, 1, '$K = qV = (1.6\times10^{-19})(1000) = 1.6\times10^{-16}\ \text{J} = 1000\ \text{eV}$.', 'Electrostatics'),
  ('A parallel-plate capacitor has plate area $0.010\ \text{m}^{2}$ and separation $2.0\ \text{mm}$. With a dielectric of $\kappa = 4$ filling the gap, the capacitance is:', '["$4.43\\times10^{-11}\\ \\text{F}$","$7.08\\times10^{-10}\\ \\text{F}$","$1.77\\times10^{-10}\\ \\text{F}$","$3.54\\times10^{-10}\\ \\text{F}$"]'::jsonb, 2, '$C = \kappa\varepsilon_{0}A/d = 4(8.85\times10^{-12})(0.01)/(2\times10^{-3}) = 1.77\times10^{-10}\ \text{F}$.', 'Capacitors and Dielectrics'),
  ('A $10\ \mu\text{F}$ capacitor is charged to $100\ \text{V}$. The charge on it is:', '["$1.0\\times10^{-5}\\ \\text{C}$","$1.0\\times10^{-1}\\ \\text{C}$","$5.0\\times10^{-2}\\ \\text{C}$","$1.0\\times10^{-3}\\ \\text{C}$"]'::jsonb, 3, '$Q = CV = (10\times10^{-6})(100) = 1.0\times10^{-3}\ \text{C}$.', 'Capacitors and Dielectrics'),
  ('How much energy is stored in a $10\ \mu\text{F}$ capacitor charged to $100\ \text{V}$?', '["$0.050\\ \\text{J}$","$0.10\\ \\text{J}$","$0.0010\\ \\text{J}$","$0.50\\ \\text{J}$"]'::jsonb, 0, '$U = \tfrac{1}{2}CV^{2} = \tfrac{1}{2}(10\times10^{-6})(10^{4}) = 0.050\ \text{J}$.', 'Capacitors and Dielectrics'),
  ('A capacitor charged to $100\ \text{V}$ discharges through a resistor. After two time constants the voltage is about:', '["$36.8\\ \\text{V}$","$13.5\\ \\text{V}$","$50\\ \\text{V}$","$86.5\\ \\text{V}$"]'::jsonb, 1, '$V = V_{0}e^{-t/\tau}$. At $t = 2\tau$: $V = 100e^{-2} = 13.5\ \text{V}$.', 'Capacitors and Dielectrics'),
  ('A $24\ \Omega$ heater is connected to a $12\ \text{V}$ d.c. supply. The power dissipated is:', '["$288\\ \\text{W}$","$0.5\\ \\text{W}$","$6.0\\ \\text{W}$","$2.0\\ \\text{W}$"]'::jsonb, 2, '$P = V^{2}/R = 144/24 = 6.0\ \text{W}$.', 'Current Electricity and DC Circuits'),
  ('A copper wire of length $10\ \text{m}$ and diameter $1.0\ \text{mm}$ has resistivity $1.7\times10^{-8}\ \Omega\,\text{m}$. Its resistance is about:', '["$0.87\\ \\Omega$","$0.054\\ \\Omega$","$2.2\\ \\Omega$","$0.22\\ \\Omega$"]'::jsonb, 3, '$R = \rho L/A$ with $A = \pi(0.5\times10^{-3})^{2} = 7.85\times10^{-7}\ \text{m}^{2}$. $R = (1.7\times10^{-8})(10)/(7.85\times10^{-7}) = 0.22\ \Omega$.', 'Current Electricity and DC Circuits'),
  ('A uniform wire of resistance $100\ \Omega$ is drawn out uniformly to twice its length. Its new resistance is:', '["$400\\ \\Omega$","$200\\ \\Omega$","$50\\ \\Omega$","$25\\ \\Omega$"]'::jsonb, 0, 'Volume is fixed, so doubling the length halves the area. $R = \rho L/A$ increases by $2\times2 = 4$.', 'Current Electricity and DC Circuits'),
  ('Two batteries, $6\ \text{V}$ and $3\ \text{V}$ (negligible internal resistance), oppose each other in a series loop containing $2\ \Omega$, $4\ \Omega$ and $1\ \Omega$ resistors. The current is:', '["$1.29\\ \\text{A}$","$0.43\\ \\text{A}$","$0.86\\ \\text{A}$","$1.00\\ \\text{A}$"]'::jsonb, 1, 'Net e.m.f. $= 6 - 3 = 3\ \text{V}$; total resistance $= 7\ \Omega$. $I = 3/7 = 0.43\ \text{A}$ (Kirchhoff''s voltage law).', 'Current Electricity and DC Circuits'),
  ('A $12\ \text{V}$ supply is connected across a $3\ \Omega$ and a $6\ \Omega$ resistor in series. The potential difference across the $6\ \Omega$ resistor is:', '["$4.0\\ \\text{V}$","$6.0\\ \\text{V}$","$8.0\\ \\text{V}$","$12\\ \\text{V}$"]'::jsonb, 2, 'Voltage divides in proportion to resistance: $12\times6/9 = 8.0\ \text{V}$.', 'Current Electricity and DC Circuits'),
  ('A cell of e.m.f. $6.0\ \text{V}$ and internal resistance $0.50\ \Omega$ is connected to a $2.5\ \Omega$ resistor. The terminal voltage is:', '["$6.0\\ \\text{V}$","$1.0\\ \\text{V}$","$2.5\\ \\text{V}$","$5.0\\ \\text{V}$"]'::jsonb, 3, '$I = \varepsilon/(R + r) = 6/3 = 2\ \text{A}$. $V = \varepsilon - Ir = 6 - 1 = 5.0\ \text{V}$.', 'Current Electricity and DC Circuits'),
  ('The Bohr radius is $0.0529\ \text{nm}$. The radius of the $n = 3$ orbit of hydrogen is:', '["$0.476\\ \\text{nm}$","$0.159\\ \\text{nm}$","$0.0176\\ \\text{nm}$","$1.43\\ \\text{nm}$"]'::jsonb, 0, '$r_{n} = n^{2}a_{0} = 9(0.0529) = 0.476\ \text{nm}$.', 'Atomic and Nuclear Physics'),
  ('Using $R_{H} = 1.097\times10^{7}\ \text{m}^{-1}$, the wavelength of the first Balmer line ($n = 3\to2$) is:', '["$486\\ \\text{nm}$","$656\\ \\text{nm}$","$122\\ \\text{nm}$","$1875\\ \\text{nm}$"]'::jsonb, 1, '$1/\lambda = R_{H}(1/2^{2} - 1/3^{2}) = (1.097\times10^{7})(5/36)$, so $\lambda = 6.56\times10^{-7}\ \text{m} = 656\ \text{nm}$.', 'Atomic and Nuclear Physics'),
  ('The energy of a photon emitted when a hydrogen electron falls from $n = 2$ to $n = 1$ is:', '["$13.6\\ \\text{eV}$","$3.4\\ \\text{eV}$","$10.2\\ \\text{eV}$","$1.9\\ \\text{eV}$"]'::jsonb, 2, '$E_{n} = -13.6/n^{2}$. $E_{2} - E_{1} = -3.4 - (-13.6) = 10.2\ \text{eV}$.', 'Atomic and Nuclear Physics'),
  ('A radioactive sample has a half-life of $5.0$ days. If $800\ \text{mg}$ is present initially, the mass remaining after $15$ days is:', '["$200\\ \\text{mg}$","$266\\ \\text{mg}$","$400\\ \\text{mg}$","$100\\ \\text{mg}$"]'::jsonb, 3, '$15$ days is $3$ half-lives: $800\times(1/2)^{3} = 100\ \text{mg}$.', 'Atomic and Nuclear Physics'),
  ('A nuclide has a half-life of $5.0$ days. Its decay constant is about:', '["$1.6\\times10^{-6}\\ \\text{s}^{-1}$","$1.4\\times10^{-1}\\ \\text{s}^{-1}$","$2.3\\times10^{-6}\\ \\text{s}^{-1}$","$1.6\\times10^{-3}\\ \\text{s}^{-1}$"]'::jsonb, 0, '$\lambda = \ln2/T_{1/2} = 0.693/(5\times86\,400) = 1.6\times10^{-6}\ \text{s}^{-1}$.', 'Atomic and Nuclear Physics'),
  ('In a nuclear reaction the total mass decreases by $0.0020\ \text{u}$. The energy released is about:', '["$18.6\\ \\text{MeV}$","$1.86\\ \\text{MeV}$","$0.186\\ \\text{MeV}$","$931\\ \\text{MeV}$"]'::jsonb, 1, '$E = \Delta m\times931.49 = 0.002\times931.49 = 1.86\ \text{MeV}$.', 'Atomic and Nuclear Physics'),
  ('A beta-minus decay changes the nucleus $^{A}_{Z}\text{X}$ into:', '["$^{A}_{Z-1}\\text{Y}$","$^{A-4}_{Z-2}\\text{Y}$","$^{A}_{Z+1}\\text{Y}$","$^{A-1}_{Z}\\text{Y}$"]'::jsonb, 2, 'A neutron turns into a proton, so $A$ is unchanged and $Z$ rises by one.', 'Atomic and Nuclear Physics'),
  ('Gamma rays differ from X-rays mainly in that gamma rays:', '["are charged particles","cannot ionise matter","travel more slowly in vacuum","come from the nucleus"]'::jsonb, 3, 'Both are electromagnetic radiation travelling at $c$. Gamma rays originate in nuclear transitions, X-rays in electron transitions or deceleration.', 'Atomic and Nuclear Physics')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where (subject_name ilike 'PHY 102%' or subject_id = 'phy-124-electricity-magnetism-atomic')
     and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'phy-124-electricity-magnetism-atomic'),
       coalesce(t.subject_name, 'PHY 102: Electricity, Magnetism and Atomic Physics'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering'),
       coalesce(t.department, 'Physics and Astronomy'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'second'),
       coalesce(t.units, 3)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'phy-124-electricity-magnetism-atomic') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_id = 'phy-124-electricity-magnetism-atomic'
 group by 1, 2;
